fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let max_len = m.max(n);
    
    let broadcasted_a = if m == 1 && n > 1 {
        // Broadcast a to match length of b
        vec![a[0]; max_len]
    } else {
        // Either same length or a is longer - return copy of a
        a.clone()
    };
    
    let broadcasted_b = if n == 1 && m > 1 {
        // Broadcast b to match length of a
        vec![b[0]; max_len]
    } else {
        // Either same length or b is longer - return copy of b
        b.clone()
    };
    
    (broadcasted_a, broadcasted_b)
}